/**
 * Delete a user by UUID
 */
export const deleteUserMutation = (
  options?: Partial<Options<DeleteUserData>>
): UseMutationOptions<DeleteUserResponse, DeleteUserError, Options<DeleteUserData>> => {
  const mutationOptions: UseMutationOptions<
    DeleteUserResponse,
    DeleteUserError,
    Options<DeleteUserData>
  > = {
    mutationFn: async fnOptions => {
      const { data } = await deleteUser({
        ...options,
        ...fnOptions,
        throwOnError: true,
      });
      return data;
    },
  };
  return mutationOptions;
};

export type QueryKey<TOptions extends Options> = [
  Pick<TOptions, 'baseUrl' | 'body' | 'headers' | 'path' | 'query'> & {
    _id: string;
    _infinite?: boolean;
    tags?: ReadonlyArray<string>;
  },
];

const createQueryKey = <TOptions extends Options>(
  id: string,
  options?: TOptions,
  infinite?: boolean,
  tags?: ReadonlyArray<string>
): [QueryKey<TOptions>[0]] => {
  const params: QueryKey<TOptions>[0] = {
    _id: id,
    baseUrl: options?.baseUrl || (options?.client ?? client).getConfig().baseUrl,
  } as QueryKey<TOptions>[0];
  if (infinite) {
    params._infinite = infinite;
  }
  if (tags) {
    params.tags = tags;
  }
  if (options?.body) {
    params.body = options.body;
  }
  if (options?.headers) {
    params.headers = options.headers;
  }
  if (options?.path) {
    params.path = options.path;
  }
  if (options?.query) {
    params.query = options.query;
  }
  return [params];
};

export const getUserByUuidQueryKey = (options: Options<GetUserByUuidData>) =>
  createQueryKey('getUserByUuid', options);

/**
 * Get a user by UUID
 *
 * Returns the full User record to the account holder, to platform administrators, to a manager of one of the account's organisations, and to a caller with a working relationship to them - the instructor whose class they are enrolled or waitlisted on, or the course creator whose course or programme they are enrolled on or have applied to teach. Every other authenticated caller receives the UserSummary directory projection: display identity only, with no email, phone number, date of birth or username.
 */
export const getUserByUuidOptions = (options: Options<GetUserByUuidData>) =>
  queryOptions<
    GetUserByUuidResponse,
    GetUserByUuidError,
    GetUserByUuidResponse,
    ReturnType<typeof getUserByUuidQueryKey>
  >({
    queryFn: async ({ queryKey, signal }) => {
      const { data } = await getUserByUuid({
        ...options,
        ...queryKey[0],
        signal,
        throwOnError: true,
      });
      return data;
    },
    queryKey: getUserByUuidQueryKey(options),
  });

