export const getAllInstructorsQueryKey = (options: Options<GetAllInstructorsData>) =>
  createQueryKey('getAllInstructors', options);

/**
 * Get all instructors
 *
 *  Fetches a paginated list of instructors.
 *
 * **Free-text search (`q`):** optional, and served only by the instructors search index:
 * `q` is matched typo-tolerantly against name, headline, skills, experience, location and
 * bio, and results come back in relevance order (or by `sort` over `full_name`,
 * `rating_avg`, `review_count`, `created_at`). There is no database fallback: when search
 * or the index's reads are off, or the engine is down, a request with `q` answers 503
 * ("Search is unavailable").
 *
 * **Visibility:** the same with or without `q`. Platform admins see every instructor;
 * everyone else sees admin-verified instructors plus their own profile.
 *
 * **Near me (`near=lat,lng&radius_km=`):** optional, with or without `q`, signed-in callers
 * only. Returns only verified instructors who opted in (`PUT /{uuid}/location-search`) and
 * have a location, within the radius (clamped to 2-100 km, default 10). `near` is rounded
 * to 2 decimals on the server and never stored or logged. Without `q` results are nearest
 * first; with `q`, by relevance. Each row carries `distance_band` (`<2 km`, `2-5 km`,
 * `5-10 km`, `10-25 km`, `>25 km`) and coordinates rounded to 2 decimals; never metres.
 * Served only by the index: 503 ("Search is unavailable") when it cannot answer.
 *
 */
export const getAllInstructorsOptions = (options: Options<GetAllInstructorsData>) =>
  queryOptions<
    GetAllInstructorsResponse,
    GetAllInstructorsError,
    GetAllInstructorsResponse,
    ReturnType<typeof getAllInstructorsQueryKey>
  >({
    queryFn: async ({ queryKey, signal }) => {
      const { data } = await getAllInstructors({
        ...options,
        ...queryKey[0],
        signal,
        throwOnError: true,
      });
      return data;
    },
    queryKey: getAllInstructorsQueryKey(options),
  });

